style.css:
@-moz-document domain("smiceplus.com") {
/* Body and general elements */
  body {
    background-color: #1a1a1a;
    color: #e0e0e0;
  }

  /* Headers and text */
  h1, h2, h3, h4, h5, h6 {
    color: #e0e0e0;
  }

  /* Cards and panels */
  .card, .panel {
    background-color: #2d2d2d;
    border-color: #404040;
  }

  .card-header, .panel-header {
    background-color: #2d2d2d;
    border-bottom-color: #404040;
  }

  /* Forms and inputs */
  .admin-form input[type="text"],
  .admin-form input[type="password"],
  .admin-form input[type="email"],
  .admin-form textarea,
  .admin-form select {
    background-color: #1a1a1a;
    border-color: #404040;
    color: #e0e0e0;
  }

  .admin-form input:focus,
  .admin-form textarea:focus,
  .admin-form select:focus {
    background-color: #2d2d2d;
    border-color: #4a90e2;
  }

  /* Tables */
  table {
    background-color: #2d2d2d;
    color: #e0e0e0;
  }

  th {
    background-color: #1a1a1a;
    color: #e0e0e0;
  }

  tr:nth-child(even) {
    background-color: #1a1a1a;
  }

  tr:hover {
    background-color: #3a3a3a;
  }

  /* Navigation */
  .navbar, .sidebar {
    background-color: #2d2d2d;
    border-color: #404040;
  }

  .nav-link {
    color: #e0e0e0;
  }

  .nav-link:hover {
    color: #66b3ff;
    background-color: #3a3a3a;
  }

  /* Buttons */
  .btn-default {
    background-color: #2d2d2d;
    border-color: #404040;
    color: #e0e0e0;
  }

  .btn-default:hover {
    background-color: #3a3a3a;
    border-color: #404040;
    color: #e0e0e0;
  }

  /* Links */
  a {
    color: #66b3ff;
  }

  a:hover {
    color: #4a90e2;
  }

  /* Modals and dropdowns */
  .modal-content {
    background-color: #2d2d2d;
    border-color: #404040;
  }

  .dropdown-menu {
    background-color: #2d2d2d;
    border-color: #404040;
  }

  .dropdown-item {
    color: #e0e0e0;
  }

  .dropdown-item:hover {
    background-color: #3a3a3a;
    color: #e0e0e0;
  }

  /* Charts and visualizations */
  .apexcharts-canvas {
    background-color: #2d2d2d !important;
  }

  .apexcharts-text {
    fill: #e0e0e0 !important;
  }

  .apexcharts-grid line {
    stroke: #404040;
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #1a1a1a;
  }

  ::-webkit-scrollbar-thumb {
    background: #404040;
    border-radius: 5px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #3a3a3a;
  }

  /* Tooltips */
  .tooltip-inner {
    background-color: #2d2d2d;
    color: #e0e0e0;
  }

  /* Grid and layout */
  .ui-grid {
    border-color: #404040;
  }

  .ui-grid-header {
    background-color: #1a1a1a;
    border-color: #404040;
  }

  .ui-grid-row:nth-child(even) {
    background-color: #1a1a1a;
  }

  .ui-grid-row:nth-child(odd) {
    background-color: #2d2d2d;
  }

  /* Notifications and alerts */
  .alert {
    background-color: #2d2d2d;
    border-color: #404040;
    color: #e0e0e0;
  }

  /* Loading spinners */
  .spinner {
    border-color: #404040;
    border-top-color: #4a90e2;
  }

  /* SMICE+ specific elements */
  .chosen-container, .chosen-drop {
    background-color: #2d2d2d;
    border-color: #404040;
  }

  .chosen-container .chosen-results li {
    color: #e0e0e0;
  }

  .chosen-container .chosen-results li.highlighted {
    background-color: #3a3a3a;
    color: #66b3ff;
  }

  .nano > .nano-pane {
    background-color: #404040;
  }

  .nano > .nano-pane > .nano-slider {
    background-color: #666666;
  }
}
